function mergeItems(base, extra) {
  // BUG: extra.length from user JSON may be huge
  base.length = Math.max(base.length, extra.length);
  for (let i = 0; i < extra.length; i++) base[i] = extra[i];
}

// Safer: iterate own keys or validate length cap
function mergeSafe(base, extra, max = 10_000) {
  if (!Array.isArray(extra) || extra.length > max) throw new RangeError("invalid extra");
  return base.concat(extra);
}
